package jwtx_test

import (
	"testing"
	"time"

	"github.com/egdaemon/eg/internal/jwtx"
	"github.com/golang-jwt/jwt/v4"
	"github.com/stretchr/testify/require"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestClaimsOptionAuthnExpiration(t *testing.T) {
	issued := time.Date(2025, 3, 10, 8, 30, 45, 0, time.UTC)

	rc := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(issued),
	}

	jwtx.ClaimsOptionAuthnExpiration()(&rc)

	require.Equal(t, issued.Add(7*24*time.Hour), rc.ExpiresAt.Time)
}

func TestClaimsOptionAuthnExpirationOverwritesExistingExpiresAt(t *testing.T) {
	issued := time.Date(2025, 6, 15, 12, 0, 0, 0, time.UTC)
	preExisting := time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC)

	rc := jwt.RegisteredClaims{
		IssuedAt:  jwt.NewNumericDate(issued),
		ExpiresAt: jwt.NewNumericDate(preExisting),
	}

	jwtx.ClaimsOptionAuthnExpiration()(&rc)

	require.Equal(t, issued.Add(7*24*time.Hour), rc.ExpiresAt.Time)
	require.NotEqual(t, preExisting, rc.ExpiresAt.Time)
}

func TestClaimsOptionAuthnExpirationZeroIssuedAt(t *testing.T) {
	rc := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(time.Time{}),
	}

	jwtx.ClaimsOptionAuthnExpiration()(&rc)

	require.Equal(t, time.Time{}.Add(7*24*time.Hour), rc.ExpiresAt.Time)
}

func TestClaimsOptionAuthnExpirationOffsetIsExactlySevenDays(t *testing.T) {
	issued := time.Date(2024, 11, 30, 23, 59, 59, 999999999, time.UTC)

	rc := jwt.RegisteredClaims{
		IssuedAt: jwt.NewNumericDate(issued),
	}

	jwtx.ClaimsOptionAuthnExpiration()(&rc)

	require.Equal(t, 7*24*time.Hour, rc.ExpiresAt.Time.Sub(rc.IssuedAt.Time))
}
